d=docx.Document()
st=d.styles["Normal"]; st.font.name="Calibri"; st.font.size=Pt(11)
d.add_heading("Paper 1 co-author workbook (version 2, 6 November 2026)",0)
d.add_paragraph("What Prices Cannot Tell a Market Supervisor — Niroula, Niroula and Khatiwada")
d.add_paragraph("This version replaces the workbook of 2 November 2026, whose model, numbering and several claims did not match the manuscript. "
 "Questions now follow the SSRN working paper of 5–6 November 2026 (theorem numbers as in that PDF), and incorporate the corrections Sujan Khatiwada recorded after reading the 2–3 November PDFs. "
 "The note under each question says which of his items it reflects.")
n=0
for part,qs in Q:
    d.add_heading(part,1)
    for title,text,note in qs:
        n+=1
        d.add_heading(f"Question {n}: {title}",2)
        d.add_paragraph(text)
        p=d.add_paragraph(); r=p.add_run("Correction source: "+note); r.italic=True; r.font.size=Pt(9)
d.add_heading("Question 31: Section-by-section editorial log",1)
d.add_paragraph("Open the SSRN PDF and the LaTeX source paper1.tex. For each part below record (a) text you revised or proposed, (b) equations, derivations or tables you checked and how, and (c) open objections. Use theorem numbers and table IDs.")
for sec in ["Title, abstract and declarations","1 Introduction","2 Model and motivating examples","3 The identification boundary (Theorem 3.1, Proposition 3.3)","4 Probing resources, memory resolution and money (Theorem 4.1)","5 Unknown mixtures and passive data (Theorems 5.1–5.5, Corollary 5.3)","6 What disclosure buys (Propositions 6.1–6.6, Theorem 6.2)","7 Implications for supervision and market design","8 Conclusion","Supplement: proofs, further results, empirics (S16–S19), scorecard (Table S29), reproducibility and formal verification"]:
    d.add_paragraph(sec, style="List Number")
d.save(sys.argv[1]); print("questions",n)
